import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from 'react'
import { Link } from 'react-router-dom'
import { ArrowRightLeft, Calculator, CheckCircle2, ClipboardCheck, Download, History, Package, Plus, Search, Settings2, ShieldCheck, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { useCompany } from '@/hooks/useCompany'
import { useCompanyRecords } from '@/hooks/useCompanyRecords'
import { money, today, type Account, type Books, type Entry } from '@/lib/accounting'
import {
  assetBalances, assetReconciliation, assetTaxSchedule, emptyAssetAccounts, emptyAssetControl,
  previewAssetCommand, validateAssetAllocation, validateAssetCommand,
  type AssetAccounts, type AssetCommand, type AssetControl, type AssetInput, type AssetPolicy,
  type AssetPreview, type AssetRecord, type AssetRun,
} from '@/lib/assets'

const input = 'w-full rounded-md border border-input bg-card px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-ring'
const panel = 'rounded-xl border border-border bg-card p-5 shadow-[0_1px_2px_rgb(16_45_80_/_0.02)] sm:p-6'

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="grid gap-1.5 text-sm font-medium"><span>{label}</span>{children}{hint && <span className="text-xs font-normal leading-5 text-muted-foreground">{hint}</span>}</label>
}
function Modal({ title, busy, close, children }: { title: string; busy: boolean; close: () => void; children: ReactNode }) {
  const dialog = useRef<HTMLDialogElement>(null), id = useId()
  useEffect(() => { dialog.current?.showModal(); const node = dialog.current; return () => node?.close() }, [])
  return <dialog ref={dialog} aria-labelledby={id} className="ubb-modal m-auto max-h-[92svh] w-[min(96vw,1000px)] overflow-auto rounded-2xl border border-border bg-card p-5 text-foreground shadow-xl backdrop:bg-slate-950/40 sm:p-7" onCancel={event => { event.preventDefault(); if (!busy) close() }}><div className="mb-5 flex items-start justify-between gap-4"><h2 id={id} className="text-xl font-semibold">{title}</h2><Button type="button" size="icon" variant="ghost" disabled={busy} aria-label="Close asset dialog" onClick={close}><X size={18} /></Button></div>{children}</dialog>
}
function AccountSelect({ accounts, value, onChange, label, optional = false }: { accounts: Account[]; value: string; onChange: (value: string) => void; label: string; optional?: boolean }) {
  return <Field label={label}><select required={!optional} className={input} value={value} onChange={event => onChange(event.target.value)}><option value="">{optional ? 'None' : 'Choose an account'}</option>{accounts.map(account => <option key={account.code} value={account.code}>{account.code} · {account.name}</option>)}</select></Field>
}
function EntryLink({ entry, id }: { entry?: Entry; id?: string }) {
  return id ? <Link className="text-primary underline underline-offset-2" to={`/accounting/journal?q=${encodeURIComponent(entry?.reference || id)}`}>{entry?.reference || id}</Link> : <span className="text-muted-foreground">No journal entry</span>
}
function amount(raw: string): number {
  if (!/^\d+(?:\.\d{1,2})?$/.test(raw)) throw Error('Enter PHP amounts with no more than two decimal places, using 0 for an intentional zero.')
  const [whole, fraction = ''] = raw.split('.'), cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'))
  if (!Number.isSafeInteger(cents)) throw Error('The amount is outside the supported range.')
  return cents
}
function decimal(value: number): string { return (value / 100).toFixed(2) }
function exportCsv(name: string, rows: (string | number | boolean)[][]) {
  const content = '\uFEFF' + rows.map(row => row.map(value => { const text = String(value); return `"${(/^[=+@\-\t\r]/.test(text) ? "'" : '') + text.replaceAll('"', '""')}"` }).join(',')).join('\r\n')
  const url = URL.createObjectURL(new Blob([content], { type: 'text/csv;charset=utf-8' })), link = document.createElement('a')
  try { link.href = url; link.download = name; document.body.appendChild(link); link.click() }
  finally { link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
}
function Empty({ title, children }: { title: string; children: ReactNode }) {
  return <div className="px-5 py-12 text-center"><Package className="mx-auto size-9 text-muted-foreground" /><h3 className="mt-4 font-semibold">{title}</h3><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{children}</p></div>
}

const actionLabels: Record<AssetCommand['kind'], string> = { register: 'Registration', depreciation: 'Depreciation', transfer: 'Custody transfer', impairment: 'Impairment', disposal: 'Disposal', reverse: 'Reversal' }
const accountLabels: Record<keyof AssetAccounts, string> = { cost: 'Asset cost', accumulatedDepreciation: 'Accumulated depreciation', depreciationExpense: 'Depreciation expense', accumulatedImpairment: 'Accumulated impairment', impairmentExpense: 'Impairment expense', disposalGain: 'Disposal gain', disposalLoss: 'Disposal loss' }
const accountTypes: Record<keyof AssetAccounts, Account['type']> = { cost: 'Asset', accumulatedDepreciation: 'Asset', depreciationExpense: 'Expense', accumulatedImpairment: 'Asset', impairmentExpense: 'Expense', disposalGain: 'Revenue', disposalLoss: 'Expense' }
const usableAccounts = (books: Books, type: Account['type']) => books.accounts.filter(account => account.type === type && !account.cash && !['1100', '2000', '1400', '2110'].includes(account.code))
type Edit = { kind: 'register' } | { kind: 'depreciation' | 'transfer' | 'impairment' | 'disposal'; assetId?: string } | { kind: 'reverse'; runId: string }
type Prepare = (command: AssetCommand, expectedRevision: number, requestId: string) => Promise<boolean>

export function AssetWorkspace() {
  const company = useCompany(), member = company?.membership
  const allowed = Boolean(member?.active), canPrepare = allowed && member?.role !== 'viewer', canReview = allowed && ['admin', 'manager'].includes(member?.role || '')
  const register = useCompanyRecords<AssetRecord>('assets', allowed), runs = useCompanyRecords<AssetRun>('assetRuns', allowed), controls = useCompanyRecords<AssetControl>('assetControl', allowed)
  const assets = register.rows, control = controls.rows.find(row => row.id === 'default') || emptyAssetControl()
  const [tab, setTab] = useState<'register' | 'reviews' | 'reconciliation' | 'tax' | 'history'>('register')
  const [search, setSearch] = useState(''), [status, setStatus] = useState('all'), [asOf, setAsOf] = useState(today())
  const [selectedId, setSelectedId] = useState(''), [editing, setEditing] = useState<Edit | null>(null), [selectedRun, setSelectedRun] = useState<string>('')
  const [busy, setBusy] = useState(false), [error, setError] = useState(''), [notice, setNotice] = useState('')
  useEffect(() => { setEditing(null); setSelectedId(''); setSelectedRun(''); setNotice(''); setError('') }, [member?.companyId, member?.uid, member?.role])
  const loading = register.loading || runs.loading || controls.loading || !company?.booksReady
  const loadError = register.error || runs.error || controls.error
  const sortedRuns = [...runs.rows].sort((a, b) => b.preparedAt.localeCompare(a.preparedAt))
  const pending = sortedRuns.filter(run => run.status === 'draft'), selected = assets.find(asset => asset.id === selectedId), review = runs.rows.find(run => run.id === selectedRun)
  const shown = assets.filter(asset => {
    const values = assetBalances(asset, asOf || today())
    return (status === 'all' || values.status === status) && `${asset.code} ${asset.name} ${asset.category} ${asset.serialNumber} ${values.custodian} ${values.location}`.toLowerCase().includes(search.toLowerCase())
  }).sort((a, b) => a.code.localeCompare(b.code))
  const totals = assets.reduce((sum, asset) => { const values = assetBalances(asset, asOf || today()); return { cost: sum.cost + values.cost, depreciation: sum.depreciation + values.depreciation, impairment: sum.impairment + values.impairment, carryingValue: sum.carryingValue + values.carryingValue } }, { cost: 0, depreciation: 0, impairment: 0, carryingValue: 0 })
  async function prepare(command: AssetCommand, expectedRevision: number, requestId: string) {
    if (!company || !canPrepare || busy || loading) return false
    setBusy(true); setError(''); setNotice('')
    try {
      const result = await company.invoke<{ id: string }>('companyAssets', { action: 'prepare', requestId, expectedRevision, command })
      setEditing(null); setTab('reviews'); if (result.id) setSelectedRun(result.id)
      setNotice('Asset action prepared. A different Company Admin or Accounting Manager must review it before it changes the register or books.')
      return true
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'The asset action could not be prepared.'); throw cause }
    finally { setBusy(false) }
  }
  async function decide(action: 'approve' | 'reject', run: AssetRun, reviewNote: string) {
    if (!company || !canReview || busy) return
    setBusy(true); setError(''); setNotice('')
    try {
      await company.invoke('companyAssets', { action, id: run.id, expectedRevision: control.revision, reviewNote })
      setSelectedRun(''); setNotice(action === 'approve' ? 'Asset action approved. The register and any required journal entry were updated together.' : 'Asset action rejected. The review remains in the action history.')
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'The asset review could not be completed.'); throw cause }
    finally { setBusy(false) }
  }
  if (!allowed || !company) return <section className={panel}><ShieldCheck className="size-8 text-primary" /><h2 className="mt-4 text-lg font-semibold">Company asset register</h2><p className="mt-2 text-sm text-muted-foreground">An active company membership is required to open the asset register.</p></section>
  if (loadError) return <p role="alert" className="rounded-xl border border-destructive/20 bg-destructive/5 p-5 text-sm text-destructive">{loadError}</p>
  if (loading) return <p role="status" className="p-6 text-sm text-muted-foreground">Loading the company asset register, reviewed actions and books…</p>
  return <div className="space-y-5">
    <div className="rounded-xl border border-primary/15 bg-accent/50 p-5"><div className="flex items-start gap-3"><Package className="mt-0.5 size-6 shrink-0 text-primary" /><div><h2 className="font-semibold">One register, connected to your books</h2><p className="mt-1 max-w-4xl text-sm leading-6 text-muted-foreground">Link a posted acquisition or prepare an opening balance. Track custody and review depreciation, impairment and disposal before posting. Book and tax policies are configured separately for each asset.</p></div></div></div>
    {error && <p role="alert" className="rounded-lg border border-destructive/20 bg-destructive/5 p-4 text-sm text-destructive">{error}</p>}
    {notice && <p role="status" className="rounded-lg border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900">{notice}</p>}
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[['Recorded cost', totals.cost], ['Accumulated depreciation', totals.depreciation], ['Accumulated impairment', totals.impairment], ['Net carrying value', totals.carryingValue]].map(([label, value]) => <div key={String(label)} className={panel}><p className="text-xs font-medium text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight tabular-nums">{money(Number(value))}</p><p className="mt-1 text-xs text-muted-foreground">Register as of {asOf || today()}</p></div>)}</div>
    <div className="flex flex-wrap gap-2 border-b pb-3" role="navigation" aria-label="Asset workspace views">{([['register', 'Asset register', Package], ['reviews', `Review queue (${pending.length})`, ClipboardCheck], ['reconciliation', 'GL reconciliation', CheckCircle2], ['tax', 'Book / tax schedule', Calculator], ['history', 'Action history', History]] as const).map(([id, label, Icon]) => <Button key={id} variant={tab === id ? 'default' : 'outline'} aria-pressed={tab === id} onClick={() => setTab(id)}><Icon size={15} />{label}</Button>)}</div>
    {tab === 'register' && <><div className="flex flex-wrap items-end justify-between gap-3"><div className="flex min-w-0 flex-1 flex-wrap items-end gap-3"><Field label="Search assets"><div className="relative"><Search className="absolute left-3 top-3 size-4 text-muted-foreground" /><input className={`${input} pl-9`} value={search} onChange={event => setSearch(event.target.value)} placeholder="Code, name, custodian or location" /></div></Field><Field label="Status"><select className={input} value={status} onChange={event => setStatus(event.target.value)}><option value="all">All statuses</option><option value="active">Active</option><option value="disposed">Disposed</option><option value="void">Not active</option></select></Field><Field label="As of date"><input type="date" required className={input} value={asOf} onChange={event => setAsOf(event.target.value)} /></Field></div><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={!shown.length} onClick={() => exportCsv(`asset-register-${asOf || today()}.csv`, [['Code', 'Name', 'Category', 'Serial number', 'Status', 'Location', 'Custodian', 'Acquisition date', 'Opening date', 'As of', 'Cost PHP', 'Accumulated depreciation PHP', 'Accumulated impairment PHP', 'Carrying value PHP'], ...shown.map(asset => { const b = assetBalances(asset, asOf || today()); return [asset.code, asset.name, asset.category, asset.serialNumber, b.status, b.location, b.custodian, asset.acquisitionDate, asset.basisDate, asOf || today(), decimal(b.cost), decimal(b.depreciation), decimal(b.impairment), decimal(b.carryingValue)] })])}><Download size={15} />Export register</Button>{canPrepare && <><Button variant="outline" disabled={busy || !assets.some(asset => assetBalances(asset).status === 'active')} onClick={() => setEditing({ kind: 'depreciation' })}><Calculator size={15} />Prepare depreciation</Button><Button disabled={busy} onClick={() => setEditing({ kind: 'register' })}><Plus size={15} />Register asset</Button></>}</div></div><section className="overflow-hidden rounded-xl border bg-card">{shown.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b bg-muted/40 text-xs text-muted-foreground"><tr>{['Asset', 'Custody', 'Cost', 'Depreciation / impairment', 'Carrying value', 'Status', ''].map((heading, index) => <th key={index} className="whitespace-nowrap px-4 py-3 font-medium">{heading}</th>)}</tr></thead><tbody className="divide-y">{shown.map(asset => { const values = assetBalances(asset, asOf || today()); return <tr key={asset.id}><td className="px-4 py-4"><p className="font-semibold">{asset.code} · {asset.name}</p><p className="mt-1 text-xs text-muted-foreground">{asset.category}{asset.serialNumber ? ` · ${asset.serialNumber}` : ''}</p></td><td className="px-4 py-4"><p>{values.custodian}</p><p className="mt-1 text-xs text-muted-foreground">{values.location}</p></td><td className="whitespace-nowrap px-4 py-4 tabular-nums">{money(values.cost)}</td><td className="whitespace-nowrap px-4 py-4 tabular-nums"><p>{money(values.depreciation)}</p><p className="mt-1 text-xs text-muted-foreground">Impairment {money(values.impairment)}</p></td><td className="whitespace-nowrap px-4 py-4 font-semibold tabular-nums">{money(values.carryingValue)}</td><td className="px-4 py-4 text-xs capitalize">{values.status === 'void' ? 'Not active' : values.status}</td><td className="px-4 py-4"><Button size="sm" variant="outline" onClick={() => setSelectedId(asset.id)}>Open asset</Button></td></tr> })}</tbody></table></div> : <Empty title={assets.length ? 'No matching assets' : 'Start the asset register'}>{assets.length ? 'Adjust the search or status filter to see another asset.' : 'Register an asset against a posted acquisition, or prepare its opening balances. The independent review keeps the register and books aligned.'}</Empty>}</section></>}
    {(tab === 'reviews' || tab === 'history') && <ActionList runs={tab === 'reviews' ? pending : sortedRuns} assets={assets} onOpen={run => setSelectedRun(run.id)} />}
    {tab === 'reconciliation' && <Reconciliation assets={assets} books={company.books} asOf={asOf} setAsOf={setAsOf} revision={control.revision} />}
    {tab === 'tax' && <TaxSchedule assets={assets} />}
    {selected && <AssetDetail asset={selected} books={company.books} asOf={asOf || today()} busy={busy} canPrepare={canPrepare} close={() => setSelectedId('')} onAction={kind => { setSelectedId(''); setEditing({ kind, assetId: selected.id }) }} onRun={id => { setSelectedId(''); setSelectedRun(id) }} />}
    {editing && <AssetEditor key={`${editing.kind}-${'assetId' in editing ? editing.assetId || 'new' : 'runId' in editing ? editing.runId : 'new'}`} edit={editing} assets={assets} runs={runs.rows} control={control} books={company.books} booksRevision={company.revision} busy={busy} prepare={prepare} close={() => setEditing(null)} />}
    {review && <ReviewAction key={review.id} run={review} assets={assets} books={company.books} booksRevision={company.revision} actor={member!.uid} canPrepare={canPrepare} canReview={canReview} busy={busy} decide={decide} onReverse={() => { setSelectedRun(''); setEditing({ kind: 'reverse', runId: review.id }) }} close={() => setSelectedRun('')} />}
  </div>
}

function JournalPreview({ preview, books }: { preview: AssetPreview; books: Books }) {
  return <div className="space-y-4 rounded-xl border border-primary/20 bg-accent/30 p-4"><h3 className="font-semibold">Proposed action</h3><p className="text-sm text-muted-foreground">{preview.description}</p><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs text-muted-foreground"><tr><th className="p-2">Asset</th><th className="p-2">Current / opening carrying value</th><th className="p-2">Action amount</th></tr></thead><tbody>{preview.rows.map((row, index) => <tr key={`${row.assetId}-${index}`} className="border-t"><td className="p-2">{row.code} · {row.name}</td><td className="p-2 tabular-nums">{money(row.carryingValue)}</td><td className="p-2 tabular-nums">{money(row.change)}</td></tr>)}</tbody></table></div>{preview.lines.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b text-xs text-muted-foreground"><tr><th className="p-2">Posting account</th><th className="p-2">Debit PHP</th><th className="p-2">Credit PHP</th></tr></thead><tbody>{preview.lines.map(line => <tr key={line.account} className="border-b"><td className="p-2">{line.account} · {books.accounts.find(account => account.code === line.account)?.name || 'Account unavailable'}</td><td className="p-2 tabular-nums">{money(line.debit)}</td><td className="p-2 tabular-nums">{money(line.credit)}</td></tr>)}</tbody></table></div> : <p className="text-sm text-muted-foreground">This action updates the asset register without creating a new journal entry.</p>}</div>
}

function ActionList({ runs, assets, onOpen }: { runs: AssetRun[]; assets: AssetRecord[]; onOpen: (run: AssetRun) => void }) {
  return <section className="overflow-hidden rounded-xl border bg-card">{runs.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b bg-muted/40 text-xs text-muted-foreground"><tr>{['Reference', 'Action / assets', 'Effective date', 'Status', 'Prepared', ''].map((label, index) => <th key={index} className="px-4 py-3 font-medium">{label}</th>)}</tr></thead><tbody className="divide-y">{runs.map(run => <tr key={run.id}><td className="px-4 py-4 font-semibold">{run.command.reference}</td><td className="px-4 py-4"><p>{actionLabels[run.command.kind]}</p><p className="mt-1 text-xs text-muted-foreground">{run.preview.rows.map(row => row.code || assets.find(asset => asset.id === row.assetId)?.code).filter(Boolean).join(', ') || 'Saved action'}</p></td><td className="px-4 py-4">{run.command.date}</td><td className="px-4 py-4 text-xs capitalize">{run.status}</td><td className="px-4 py-4 text-xs text-muted-foreground">{run.preparedAt.slice(0, 10)}</td><td className="px-4 py-4"><Button size="sm" variant="outline" onClick={() => onOpen(run)}>Review details</Button></td></tr>)}</tbody></table></div> : <Empty title="No asset actions in this view">Prepared actions appear here for independent review. Posted and rejected actions remain in the action history.</Empty>}</section>
}

function ActionFacts({ command, books }: { command: AssetCommand; books: Books }) {
  const facts: [string, string][] = []
  if (command.kind === 'transfer') facts.push(['New location', command.location], ['New custodian', command.custodian])
  if (command.kind === 'depreciation') facts.push(['Depreciation through month', command.throughMonth])
  if (command.kind === 'impairment') facts.push(['Reviewed impairment loss', money(command.amount)])
  if (command.kind === 'disposal') facts.push(['Net disposal proceeds', money(command.proceeds)], ['Reviewed final depreciation', money(command.finalDepreciation)], ['Proceeds clearing account', `${command.proceedsAccount} · ${books.accounts.find(account => account.code === command.proceedsAccount)?.name || ''}`])
  if (command.kind === 'reverse') facts.push(['Original asset action ID', command.runId])
  if (command.kind === 'register') {
    const value = command.input
    facts.push(['Acquisition date', value.acquisitionDate], ['Available-for-use date', value.inServiceDate], ['Register opening date', value.basisDate], ['Capitalized cost', money(value.cost)], ['Opening accumulated depreciation', money(value.openingDepreciation)], ['Opening accumulated impairment', money(value.openingImpairment)], ['Tax basis', money(value.taxPolicy.basis)], ['Opening tax depreciation', money(value.taxPolicy.openingDepreciation)])
  }
  return <div className="space-y-3"><dl className="grid gap-3 rounded-lg border p-4 sm:grid-cols-2">{facts.map(([label, value]) => <div key={label}><dt className="text-xs text-muted-foreground">{label}</dt><dd className="mt-1 break-words text-sm font-medium">{value}</dd></div>)}</dl>{command.kind === 'register' && <details className="rounded-lg border p-4"><summary className="cursor-pointer text-sm font-semibold">Registration source and account mappings</summary>{command.input.sourceMode === 'existing_entry' ? <p className="mt-3 text-sm">Source entry: <EntryLink id={command.input.sourceEntryId} entry={books.entries.find(entry => entry.id === command.input.sourceEntryId)} /></p> : <p className="mt-3 text-sm">Opening equity: {command.input.openingEquityAccount} · {books.accounts.find(account => account.code === command.input.openingEquityAccount)?.name}</p>}<dl className="mt-3 grid gap-3 sm:grid-cols-2">{(Object.keys(accountLabels) as (keyof AssetAccounts)[]).map(key => <div key={key}><dt className="text-xs text-muted-foreground">{accountLabels[key]}</dt><dd className="mt-1 text-sm">{command.input.accounts[key]} · {books.accounts.find(account => account.code === command.input.accounts[key])?.name}</dd></div>)}</dl></details>}</div>
}

function ReviewAction({ run, assets, books, booksRevision, actor, canPrepare, canReview, busy, decide, onReverse, close }: { run: AssetRun; assets: AssetRecord[]; books: Books; booksRevision: number; actor: string; canPrepare: boolean; canReview: boolean; busy: boolean; decide: (action: 'approve' | 'reject', run: AssetRun, note: string) => Promise<void>; onReverse: () => void; close: () => void }) {
  const [note, setNote] = useState(''), [checked, setChecked] = useState(false)
  const [error, setError] = useState('')
  const submit = async (action: 'approve' | 'reject') => { setError(''); try { await decide(action, run, note) } catch (cause) { setError(cause instanceof Error ? cause.message : 'The review could not be saved.') } }
  const stale = run.preparedBooksRevision !== booksRevision || Object.entries(run.assetVersions).some(([id, version]) => assets.find(asset => asset.id === id)?.version !== version)
  const own = run.preparedBy === actor
  return <Modal title={`${actionLabels[run.command.kind]} · ${run.command.reference}`} busy={busy} close={close}><div className="space-y-5"><div className="flex flex-wrap gap-x-6 gap-y-2 text-sm"><p>Status: <b className="capitalize">{run.status}</b></p><p>Effective date: <b>{run.command.date}</b></p><p>Prepared: {run.preparedAt.slice(0, 10)}</p></div>{'note' in run.command && <p className="whitespace-pre-wrap rounded-lg bg-muted/50 p-4 text-sm">{run.command.note}</p>}{run.command.kind === 'register' && <div className="rounded-lg border p-4 text-sm"><p><b>{run.command.input.code} · {run.command.input.name}</b></p><p className="mt-1">{run.command.input.sourceMode === 'existing_entry' ? 'Links an existing posted acquisition / opening entry.' : 'Creates a new opening balance journal on approval.'}</p><p className="mt-1 text-muted-foreground">Custody: {run.command.input.custodian} · {run.command.input.location}</p><PolicySummary book={run.command.input.bookPolicy} tax={run.command.input.taxPolicy} /></div>}{run.command.kind === 'disposal' && <p className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">Net proceeds are posted to the selected disposal clearing account. Actual cash collection and any tax effects must be recorded and reviewed separately.</p>}<ActionFacts command={run.command} books={books} /><JournalPreview preview={run.preview} books={books} />{run.entryId && <p className="text-sm">Posted entry: <EntryLink id={run.entryId} entry={books.entries.find(entry => entry.id === run.entryId)} /></p>}{run.reviewNote && <p className="rounded-lg bg-muted/50 p-4 text-sm">Review note: {run.reviewNote}</p>}{error && <p role="alert" className="text-sm text-destructive">{error}</p>}{run.status === 'posted' && run.command.kind !== 'reverse' && canPrepare && <Button variant="outline" disabled={busy} onClick={onReverse}>Prepare reversal</Button>}{run.status === 'draft' && <div className="space-y-4 border-t pt-5">{stale && <p role="alert" className="rounded-lg bg-amber-50 p-3 text-sm text-amber-900">The company books or asset records changed after this draft was prepared. Reject this draft and prepare a current action before approval.</p>}{own && <p className="text-sm text-muted-foreground">You prepared this action. Another Company Admin or Accounting Manager must approve it; you may reject your draft with a note if you have review access.</p>}{!canReview ? <p className="text-sm text-muted-foreground">A Company Admin or Accounting Manager must review this action.</p> : <><Field label="Independent review note"><textarea className={`${input} min-h-24`} value={note} onChange={event => setNote(event.target.value)} minLength={10} maxLength={2000} placeholder="Document source, policy, amounts and posting account checks." /></Field><label className="flex items-start gap-2 text-sm leading-6"><input className="mt-1.5" type="checkbox" checked={checked} onChange={event => setChecked(event.target.checked)} />I checked the source records, effective date, configured policies and proposed journal lines.</label><div className="flex flex-wrap gap-3"><Button disabled={busy || own || stale || !checked || note.trim().length < 10} onClick={() => void submit('approve')}>Approve asset action</Button><Button variant="outline" disabled={busy || note.trim().length < 10} onClick={() => void submit('reject')}>Reject with note</Button></div></>}</div>}</div></Modal>
}

function PolicySummary({ book, tax }: { book: AssetPolicy; tax: AssetInput['taxPolicy'] }) {
  return <div className="mt-4 grid gap-3 md:grid-cols-2">{[['Book policy', book], ['Tax schedule policy', tax]].map(([label, value]) => { const policy = value as AssetPolicy; return <div key={String(label)} className="rounded-lg border p-3 text-sm"><p className="font-semibold">{String(label)}</p><p className="mt-1">{policy.method === 'straight_line' ? `Straight line · ${policy.usefulLifeMonths} remaining months` : 'No automatic depreciation'}</p><p className="mt-1 text-xs text-muted-foreground">Effective month {policy.startMonth} · Residual value {money(policy.residualValue)}</p><p className="mt-2 whitespace-pre-wrap text-xs leading-5">{policy.note}</p></div> })}</div>
}

function AssetDetail({ asset, books, asOf, busy, canPrepare, close, onAction, onRun }: { asset: AssetRecord; books: Books; asOf: string; busy: boolean; canPrepare: boolean; close: () => void; onAction: (kind: 'depreciation' | 'transfer' | 'impairment' | 'disposal') => void; onRun: (id: string) => void }) {
  const values = assetBalances(asset, asOf), current = assetBalances(asset)
  return <Modal title={`${asset.code} · ${asset.name}`} busy={busy} close={close}><div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[['Category', asset.category], ['Serial number', asset.serialNumber || 'Not recorded'], ['Custodian', values.custodian], ['Location', values.location], ['Acquired', asset.acquisitionDate], ['Available for use', asset.inServiceDate], ['Register opening', asset.basisDate], ['Carrying value', money(values.carryingValue)]].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-medium">{value}</p></div>)}</div><p className="text-xs text-muted-foreground">Values shown as of {asOf}. Current status: {current.status === 'void' ? 'not active' : current.status}.</p>{canPrepare && current.status === 'active' && <div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => onAction('transfer')}><ArrowRightLeft size={15} />Transfer custody</Button><Button variant="outline" onClick={() => onAction('depreciation')}><Calculator size={15} />Depreciation</Button><Button variant="outline" onClick={() => onAction('impairment')}>Impairment</Button><Button variant="outline" onClick={() => onAction('disposal')}>Disposal</Button></div>}<details open className="rounded-xl border p-4"><summary className="cursor-pointer font-semibold"><span className="inline-flex items-center gap-2"><Settings2 size={16} />Reviewed book and tax policies</span></summary><PolicySummary book={asset.bookPolicy} tax={asset.taxPolicy} /><p className="mt-3 text-xs text-muted-foreground">Tax basis {money(asset.taxPolicy.basis)} · Opening tax depreciation {money(asset.taxPolicy.openingDepreciation)}. The tax schedule is a working paper and does not post to the general ledger or file a return.</p></details><details className="rounded-xl border p-4"><summary className="cursor-pointer font-semibold">Source and posting accounts</summary><p className="mt-3 text-sm">Source: {asset.sourceMode === 'existing_entry' ? <EntryLink id={asset.sourceEntryId} entry={books.entries.find(entry => entry.id === asset.sourceEntryId)} /> : 'Reviewed opening journal'}</p><dl className="mt-3 grid gap-3 sm:grid-cols-2">{Object.entries(accountLabels).map(([key, label]) => <div key={key}><dt className="text-xs text-muted-foreground">{label}</dt><dd className="mt-1 text-sm">{asset.accounts[key as keyof AssetAccounts]} · {books.accounts.find(account => account.code === asset.accounts[key as keyof AssetAccounts])?.name}</dd></div>)}</dl>{asset.notes && <p className="mt-4 whitespace-pre-wrap text-sm">{asset.notes}</p>}</details><div><h3 className="font-semibold">Asset movement history</h3><p className="mt-1 text-xs text-muted-foreground">All recorded movements, including reviewed reversals, remain visible.</p><div className="mt-3 space-y-3">{[...asset.events].reverse().map(event => <div key={event.id} className="rounded-lg border p-4 text-sm"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-semibold">{event.reference} · {actionLabels[event.kind]}</p><p className="mt-1 text-xs text-muted-foreground">{event.date}{event.throughMonth ? ` · Through ${event.throughMonth}` : ''}</p></div><Button size="sm" variant="outline" onClick={() => onRun(event.runId)}>Open reviewed action</Button></div><p className="mt-2 whitespace-pre-wrap text-xs leading-5">{event.note}</p>{(event.location || event.custodian) && <p className="mt-2 text-xs">{event.custodian} · {event.location}</p>}<p className="mt-2 text-xs">Cost movement {money(event.costDelta)} · Depreciation movement {money(event.depreciationDelta)} · Impairment movement {money(event.impairmentDelta)}</p>{event.entryId && <p className="mt-2 text-xs"><EntryLink id={event.entryId} entry={books.entries.find(entry => entry.id === event.entryId)} /></p>}</div>)}</div></div></div></Modal>
}

function Reconciliation({ assets, books, asOf, setAsOf, revision }: { assets: AssetRecord[]; books: Books; asOf: string; setAsOf: (value: string) => void; revision: number }) {
  let rows: ReturnType<typeof assetReconciliation> = [], error = ''
  try { rows = assetReconciliation(assets, books, asOf) } catch (cause) { error = (cause as Error).message }
  const differences = rows.filter(row => row.difference !== 0)
  return <section className={panel}><div className="flex flex-wrap items-end justify-between gap-4"><div><h2 className="text-lg font-semibold">Asset register to general ledger</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-muted-foreground">Compare asset cost and accumulated balance accounts through the selected date. Ledger amounts use debits less credits. Differences may identify unregistered assets or entries needing review.</p></div><div className="flex flex-wrap items-end gap-3"><Field label="Reconciliation date"><input type="date" required className={input} value={asOf} onChange={event => setAsOf(event.target.value)} /></Field><Button variant="outline" disabled={Boolean(error) || !rows.length} onClick={() => exportCsv(`asset-gl-reconciliation-${asOf}.csv`, [['As of', asOf, 'Asset revision', revision], ['Account', 'Name', 'Register balance PHP', 'Ledger balance PHP', 'Difference PHP'], ...rows.map(row => [row.account, row.name, decimal(row.registerBalance), decimal(row.ledgerBalance), decimal(row.difference)])])}><Download size={15} />Export reconciliation</Button></div></div>{error ? <p role="alert" className="mt-4 text-sm text-destructive">{error}</p> : !rows.length ? <Empty title="No registered asset accounts">Register an asset to compare its mapped accounts with the company ledger.</Empty> : <><p className={`mt-4 rounded-lg p-3 text-sm ${differences.length ? 'bg-amber-50 text-amber-900' : 'bg-emerald-50 text-emerald-900'}`}>{differences.length ? `${differences.length} mapped account${differences.length === 1 ? '' : 's'} need reconciliation.` : 'All accounts mapped to the current asset register agree with the ledger at this date.'}</p><div className="mt-4 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b text-xs text-muted-foreground"><tr>{['Account', 'Register balance', 'Ledger balance', 'Difference'].map(label => <th key={label} className="px-3 py-3 font-medium">{label}</th>)}</tr></thead><tbody className="divide-y">{rows.map(row => <tr key={row.account}><td className="p-3">{row.account} · {row.name}</td><td className="p-3 tabular-nums">{money(row.registerBalance)}</td><td className="p-3 tabular-nums">{money(row.ledgerBalance)}</td><td className={`p-3 font-semibold tabular-nums ${row.difference ? 'text-amber-800' : 'text-emerald-800'}`}>{money(row.difference)}</td></tr>)}</tbody></table></div><p className="mt-3 text-xs text-muted-foreground">This report compares accounts mapped to registered assets. It does not assume that every fixed-asset account in the chart has been mapped.</p></>}</section>
}

function TaxSchedule({ assets }: { assets: AssetRecord[] }) {
  const [from, setFrom] = useState(`${today().slice(0, 4)}-01-01`), [to, setTo] = useState(today())
  let rows: ReturnType<typeof assetTaxSchedule>[] = [], error = ''
  try { rows = assets.map(asset => assetTaxSchedule(asset, from, to)) } catch (cause) { error = (cause as Error).message }
  return <section className={panel}><div className="flex flex-wrap items-end justify-between gap-4"><div><h2 className="text-lg font-semibold">Book and configured tax depreciation</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-muted-foreground">Compare recorded book depreciation with the asset’s reviewed monthly tax policy. No statutory life, rate, eligibility or disposal treatment is assumed. Confirm adjustments before using this working paper in a return.</p></div><Button variant="outline" disabled={Boolean(error) || !rows.length} onClick={() => exportCsv(`asset-book-tax-${from}-${to}.csv`, [['From', from, 'To', to], ['Code', 'Name', 'Book depreciation PHP', 'Configured tax depreciation PHP', 'Book less tax PHP', 'Tax basis PHP', 'Review basis', 'Review required'], ...rows.map(row => [row.code, row.name, decimal(row.bookDepreciation), decimal(row.taxDepreciation), decimal(row.adjustment), decimal(row.taxBasis), row.note, true])])}><Download size={15} />Export working paper</Button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:max-w-xl"><Field label="Period starts"><input type="date" required className={input} value={from} onChange={event => setFrom(event.target.value)} /></Field><Field label="Period ends"><input type="date" required className={input} value={to} onChange={event => setTo(event.target.value)} /></Field></div>{error ? <p role="alert" className="mt-4 text-sm text-destructive">{error}</p> : !rows.length ? <Empty title="No asset schedules yet">Register assets with separate book and tax policies to prepare a comparison.</Empty> : <div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b text-xs text-muted-foreground"><tr>{['Asset', 'Book depreciation', 'Configured tax depreciation', 'Book less tax', 'Policy basis'].map(label => <th key={label} className="p-3 font-medium">{label}</th>)}</tr></thead><tbody className="divide-y">{rows.map(row => <tr key={row.assetId}><td className="p-3">{row.code} · {row.name}</td><td className="p-3 tabular-nums">{money(row.bookDepreciation)}</td><td className="p-3 tabular-nums">{money(row.taxDepreciation)}</td><td className="p-3 tabular-nums">{money(row.adjustment)}</td><td className="max-w-sm p-3 text-xs leading-5">{row.note}</td></tr>)}</tbody></table></div>}</section>
}

type PolicyForm = { method: AssetPolicy['method'] | ''; startMonth: string; months: string; residual: string; note: string }
type RegistrationForm = Omit<AssetInput, 'cost' | 'openingDepreciation' | 'openingImpairment' | 'bookPolicy' | 'taxPolicy'> & {
  cost: string; openingDepreciation: string; openingImpairment: string; book: PolicyForm; tax: PolicyForm; taxBasis: string; taxOpening: string
}
const blankPolicy = (): PolicyForm => ({ method: '', startMonth: '', months: '', residual: '0.00', note: '' })
const blankRegistration = (): RegistrationForm => ({ code: '', name: '', category: '', serialNumber: '', acquisitionDate: '', inServiceDate: '', basisDate: '', cost: '', openingDepreciation: '0.00', openingImpairment: '0.00', location: '', custodian: '', notes: '', sourceMode: 'existing_entry', sourceEntryId: '', openingEquityAccount: '', accounts: { ...emptyAssetAccounts }, book: blankPolicy(), tax: blankPolicy(), taxBasis: '', taxOpening: '0.00' })
function policyInput(form: PolicyForm): AssetPolicy {
  if (!form.method) throw Error('Choose a book and tax schedule method explicitly.')
  return { method: form.method, startMonth: form.startMonth, usefulLifeMonths: form.method === 'none' ? 1 : Number(form.months), residualValue: amount(form.residual), note: form.note }
}
function registrationInput(form: RegistrationForm): AssetInput {
  const { cost, openingDepreciation, openingImpairment, book, tax, taxBasis, taxOpening, ...identity } = form
  return { ...identity, cost: amount(cost), openingDepreciation: amount(openingDepreciation), openingImpairment: amount(openingImpairment), bookPolicy: policyInput(book), taxPolicy: { ...policyInput(tax), basis: amount(taxBasis), openingDepreciation: amount(taxOpening) } }
}

function PolicyFields({ label, value, change }: { label: string; value: PolicyForm; change: (value: PolicyForm) => void }) {
  return <fieldset className="space-y-4 rounded-xl border p-4"><legend className="px-2 text-sm font-semibold">{label}</legend><div className="grid gap-4 sm:grid-cols-2"><Field label="Schedule method"><select required className={input} value={value.method} onChange={event => change({ ...value, method: event.target.value as PolicyForm['method'] })}><option value="">Choose a method</option><option value="straight_line">Straight-line monthly schedule</option><option value="none">No automatic depreciation</option></select></Field><Field label={value.method === 'none' ? 'Policy effective month' : 'First month in this schedule'}><input type="month" required className={input} value={value.startMonth} onChange={event => change({ ...value, startMonth: event.target.value })} /></Field>{value.method === 'straight_line' && <Field label="Remaining useful life (months)" hint="Enter the remaining life at the register opening, not the original life already partly used."><input type="number" required min={1} max={1200} step={1} className={input} value={value.months} onChange={event => change({ ...value, months: event.target.value })} /></Field>}<Field label="Residual value (PHP)"><input required inputMode="decimal" className={input} value={value.residual} onChange={event => change({ ...value, residual: event.target.value })} /></Field></div><Field label="Reviewed policy and timing basis" hint="Document the useful life, eligibility, residual value and start month, or why no automatic depreciation applies."><textarea required className={`${input} min-h-24`} maxLength={2000} value={value.note} onChange={event => change({ ...value, note: event.target.value })} /></Field></fieldset>
}

function RegistrationFields({ form, change, books }: { form: RegistrationForm; change: (value: Partial<RegistrationForm>) => void; books: Books }) {
  const entries = books.entries.filter(entry => !entry.reversalOf && !books.entries.some(row => row.reversalOf === entry.id) && (!form.basisDate || entry.date <= form.basisDate)).sort((a, b) => b.date.localeCompare(a.date))
  const source = entries.find(entry => entry.id === form.sourceEntryId)
  return <div className="space-y-5"><fieldset className="rounded-xl border p-4"><legend className="px-2 text-sm font-semibold">Asset and custody</legend><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{([['code', 'Asset code', 60, true], ['name', 'Asset name', 200, true], ['category', 'Category', 100, true], ['serialNumber', 'Serial / identifying number', 100, false], ['location', 'Location', 150, true], ['custodian', 'Custodian', 150, true]] as const).map(([key, label, max, required]) => <Field key={key} label={label}><input required={required} maxLength={max} className={input} value={form[key]} onChange={event => change({ [key]: event.target.value })} /></Field>)}{([['acquisitionDate', 'Acquisition date'], ['inServiceDate', 'Available-for-use date'], ['basisDate', 'Register opening date']] as const).map(([key, label]) => <Field key={key} label={label}><input type="date" required className={input} value={form[key]} onChange={event => change({ [key]: event.target.value })} /></Field>)}</div><div className="mt-4"><Field label="Asset notes (optional)"><textarea className={input} rows={2} maxLength={2000} value={form.notes} onChange={event => change({ notes: event.target.value })} /></Field></div></fieldset>
    <fieldset className="space-y-4 rounded-xl border p-4"><legend className="px-2 text-sm font-semibold">Source and opening values</legend><Field label="How the asset enters this register"><select required className={input} value={form.sourceMode} onChange={event => change({ sourceMode: event.target.value as AssetInput['sourceMode'] })}><option value="existing_entry">Link an existing posted acquisition / opening entry</option><option value="opening_journal">Prepare a new opening balance journal</option></select></Field><p className="text-xs leading-5 text-muted-foreground">{form.sourceMode === 'existing_entry' ? 'The selected posted entry must already contain the asset cost and any opening accumulated balances. Registration will link those values without posting them again.' : 'Approval creates an opening journal for cost, accumulated balances and opening equity. Use this only for values that have not already been posted.'}</p><div className="grid gap-4 sm:grid-cols-3">{([['cost', 'Capitalized cost (PHP)'], ['openingDepreciation', 'Opening accumulated depreciation (PHP)'], ['openingImpairment', 'Opening accumulated impairment (PHP)']] as const).map(([key, label]) => <Field key={key} label={label}><input required inputMode="decimal" className={input} value={form[key]} onChange={event => change({ [key]: event.target.value })} /></Field>)}</div>{form.sourceMode === 'existing_entry' ? <><Field label="Posted source entry"><select required className={input} value={form.sourceEntryId} onChange={event => change({ sourceEntryId: event.target.value })}><option value="">Choose a posted acquisition / opening journal</option>{entries.map(entry => <option key={entry.id} value={entry.id}>{entry.date} · {entry.reference} · {entry.description.slice(0, 90)}</option>)}</select></Field>{source && <div className="rounded-lg bg-muted/40 p-3 text-xs"><p className="font-semibold">Source lines</p>{source.lines.map((line, index) => <p key={index} className="mt-1">{line.account} · {books.accounts.find(account => account.code === line.account)?.name}: debit {money(line.debit)} · credit {money(line.credit)}</p>)}</div>}</> : <AccountSelect label="Opening balance equity account" value={form.openingEquityAccount} accounts={usableAccounts(books, 'Equity')} onChange={openingEquityAccount => change({ openingEquityAccount })} />}</fieldset>
    <fieldset className="space-y-4 rounded-xl border p-4"><legend className="px-2 text-sm font-semibold">Posting accounts</legend><p className="text-xs leading-5 text-muted-foreground">Use distinct cost, accumulated depreciation and accumulated impairment accounts. Set the expense and disposal accounts now so later actions have an explicit posting basis.</p><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{(Object.keys(accountLabels) as (keyof AssetAccounts)[]).map(key => <AccountSelect key={key} label={accountLabels[key]} accounts={usableAccounts(books, accountTypes[key])} value={form.accounts[key]} onChange={value => change({ accounts: { ...form.accounts, [key]: value } })} />)}</div><Link className="inline-block text-sm text-primary underline" to="/accounting/accounts" target="_blank" rel="noreferrer">Open chart of accounts to add an account</Link></fieldset>
    <PolicyFields label="Book depreciation policy" value={form.book} change={book => change({ book })} /><fieldset className="space-y-4 rounded-xl border p-4"><legend className="px-2 text-sm font-semibold">Separate tax working paper</legend><p className="text-xs leading-5 text-muted-foreground">Enter the reviewed tax basis and policy. These settings do not determine tax eligibility, post tax depreciation to the ledger, or submit a return.</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Reviewed tax basis (PHP)"><input required inputMode="decimal" className={input} value={form.taxBasis} onChange={event => change({ taxBasis: event.target.value })} /></Field><Field label="Opening tax depreciation (PHP)"><input required inputMode="decimal" className={input} value={form.taxOpening} onChange={event => change({ taxOpening: event.target.value })} /></Field></div><PolicyFields label="Tax depreciation policy" value={form.tax} change={tax => change({ tax })} /></fieldset>
  </div>
}

function AssetEditor({ edit, assets, runs, control, books, booksRevision, busy, prepare, close }: { edit: Edit; assets: AssetRecord[]; runs: AssetRun[]; control: AssetControl; books: Books; booksRevision: number; busy: boolean; prepare: Prepare; close: () => void }) {
  const initialAsset = 'assetId' in edit ? assets.find(asset => asset.id === edit.assetId) : undefined
  const [registration, setRegistration] = useState(blankRegistration), [reference, setReference] = useState(''), [date, setDate] = useState(today())
  const [assetId, setAssetId] = useState(initialAsset?.id || ''), [assetIds, setAssetIds] = useState(initialAsset ? [initialAsset.id] : [])
  const [throughMonth, setThroughMonth] = useState(''), [location, setLocation] = useState(initialAsset ? assetBalances(initialAsset).location : ''), [custodian, setCustodian] = useState(initialAsset ? assetBalances(initialAsset).custodian : '')
  const [impairment, setImpairment] = useState(''), [proceeds, setProceeds] = useState(''), [proceedsAccount, setProceedsAccount] = useState(''), [finalDepreciation, setFinalDepreciation] = useState('0.00')
  const [note, setNote] = useState(''), [confirmed, setConfirmed] = useState(false), [error, setError] = useState('')
  const [ready, setReady] = useState<{ command: AssetCommand; preview: AssetPreview; revision: number; booksRevision: number; requestId: string } | null>(null)
  const active = assets.filter(asset => assetBalances(asset).status === 'active'), selected = active.find(asset => asset.id === assetId)
  const eligible = active.filter(asset => asset.bookPolicy.method === 'straight_line' && assetBalances(asset).carryingValue > asset.bookPolicy.residualValue)
  const sourceRun = edit.kind === 'reverse' ? runs.find(run => run.id === edit.runId) : undefined
  const stale = Boolean(ready && (ready.revision !== control.revision || ready.booksRevision !== booksRevision) && !runs.some(run => run.id === ready.requestId))
  function changed(change: () => void) { change(); setReady(null); setError('') }
  function build(): AssetCommand {
    if (!confirmed) throw Error('Review the source, amounts and policy basis before preparing this action.')
    if (edit.kind === 'register') return { kind: 'register', reference, date: registration.basisDate, input: registrationInput(registration) }
    if (edit.kind === 'depreciation') return { kind: edit.kind, reference, date, assetIds, throughMonth, note }
    if (edit.kind === 'transfer') {
      if (selected && location === assetBalances(selected).location && custodian === assetBalances(selected).custodian) throw Error('Enter a new location or custodian for this transfer.')
      return { kind: edit.kind, reference, date, assetId, location, custodian, note }
    }
    if (edit.kind === 'impairment') return { kind: edit.kind, reference, date, assetId, amount: amount(impairment), note }
    if (edit.kind === 'disposal') return { kind: edit.kind, reference, date, assetId, proceeds: amount(proceeds), proceedsAccount, finalDepreciation: amount(finalDepreciation), note }
    if (edit.kind === 'reverse') return { kind: 'reverse', reference, date, runId: edit.runId, note }
    throw Error('Choose a supported asset action.')
  }
  function preview(event: FormEvent) {
    event.preventDefault(); setError('')
    try {
      const command = validateAssetCommand(build(), books)
      if (!(command.kind === 'register' && command.input.sourceMode === 'existing_entry') && command.date <= books.closedThrough) throw Error(`The books are locked through ${books.closedThrough}. Choose an open posting date.`)
      if (command.kind === 'register') validateAssetAllocation(command.input, books, control.allocations)
      let result: AssetPreview
      if (command.kind === 'reverse') {
        if (!sourceRun || sourceRun.status !== 'posted' || sourceRun.command.kind === 'reverse') throw Error('Choose an unreversed posted asset action.')
        if (command.date < sourceRun.command.date) throw Error('Reversal cannot precede the original action.')
        result = { ...sourceRun.preview, description: `Reverse asset action · ${sourceRun.command.reference}`, lines: sourceRun.preview.lines.map(line => ({ account: line.account, debit: line.credit, credit: line.debit })), rows: (sourceRun.resultAssetIds || []).map(id => { const asset = assets.find(asset => asset.id === id); if (!asset) throw Error('An affected asset is unavailable. Reload the register.'); return { assetId: asset.id, code: asset.code, name: asset.name, ...assetBalances(asset), change: -(asset.events.find(event => event.runId === sourceRun.id)?.depreciationExpense || 0) } }), total: -sourceRun.preview.total }
      } else result = previewAssetCommand(assets, books, command)
      setReady({ command, preview: result, revision: control.revision, booksRevision, requestId: crypto.randomUUID() })
    } catch (cause) { setReady(null); setError(cause instanceof Error ? cause.message : 'Review the asset details.') }
  }
  async function save() {
    if (!ready || stale) return
    setError('')
    try { if (!await prepare(ready.command, ready.revision, ready.requestId)) setError('The company books are not ready. Wait for loading to finish and retry.') }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'The asset action could not be prepared.') }
  }
  return <Modal title={edit.kind === 'register' ? 'Register an asset' : `Prepare ${actionLabels[edit.kind].toLowerCase()}`} busy={busy} close={close}><form className="space-y-5" onSubmit={preview}><p className="text-sm leading-6 text-muted-foreground">Preview the proposed action, then save it for independent review. The register and books change only after approval.</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Action reference"><input required className={input} maxLength={180} value={reference} onChange={event => changed(() => setReference(event.target.value))} placeholder="Your asset action reference" /></Field>{edit.kind !== 'register' && <Field label="Effective / posting date"><input type="date" required className={input} value={date} onChange={event => changed(() => setDate(event.target.value))} /></Field>}</div>
    {edit.kind === 'register' ? <RegistrationFields form={registration} books={books} change={patch => changed(() => setRegistration(old => ({ ...old, ...patch })))} /> : edit.kind === 'depreciation' ? <><Field label="Calculate depreciation through month" hint="Posting must be on or after this month end. The schedule picks up unposted months from each asset’s configured start."><input type="month" required className={input} value={throughMonth} onChange={event => changed(() => setThroughMonth(event.target.value))} /></Field><div className="rounded-xl border p-4"><div className="flex flex-wrap items-center justify-between gap-3"><h3 className="text-sm font-semibold">Assets with a remaining straight-line balance</h3><Button type="button" size="sm" variant="outline" onClick={() => changed(() => setAssetIds(assetIds.length === eligible.length ? [] : eligible.map(asset => asset.id)))}>{assetIds.length === eligible.length && eligible.length ? 'Clear selection' : 'Select all eligible'}</Button></div><div className="mt-3 max-h-64 space-y-2 overflow-auto">{eligible.map(asset => <label key={asset.id} className="flex items-center gap-3 rounded-lg bg-muted/40 p-3 text-sm"><input type="checkbox" checked={assetIds.includes(asset.id)} onChange={event => changed(() => setAssetIds(old => event.target.checked ? [...old, asset.id] : old.filter(id => id !== asset.id)))} /><span className="min-w-0 flex-1">{asset.code} · {asset.name}</span><span className="shrink-0 text-xs tabular-nums">{money(assetBalances(asset).carryingValue)}</span></label>)}{!eligible.length && <p className="text-sm text-muted-foreground">No active assets have a remaining automatic depreciation balance.</p>}</div></div></> : edit.kind === 'reverse' ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><b>Reverse {sourceRun?.command.reference || 'the selected action'}</b><p>Only the latest effective action for every affected asset can be reversed. Review the original journal and use an open posting date. The original action and reversal remain in the history.</p></div> : <><Field label="Asset"><select required className={input} value={assetId} onChange={event => changed(() => { setAssetId(event.target.value); const next = active.find(asset => asset.id === event.target.value); setLocation(next ? assetBalances(next).location : ''); setCustodian(next ? assetBalances(next).custodian : '') })}><option value="">Choose an active asset</option>{active.map(asset => <option key={asset.id} value={asset.id}>{asset.code} · {asset.name}</option>)}</select></Field>{selected && <p className="rounded-lg bg-muted/40 p-3 text-sm">Current carrying value: <b>{money(assetBalances(selected).carryingValue)}</b> · {assetBalances(selected).custodian} · {assetBalances(selected).location}</p>}{edit.kind === 'transfer' && <div className="grid gap-4 sm:grid-cols-2"><Field label="New location"><input required maxLength={150} className={input} value={location} onChange={event => changed(() => setLocation(event.target.value))} /></Field><Field label="New custodian"><input required maxLength={150} className={input} value={custodian} onChange={event => changed(() => setCustodian(event.target.value))} /></Field></div>}{edit.kind === 'impairment' && <Field label="Reviewed impairment loss (PHP)" hint="Enter the reviewed loss amount. It cannot exceed current carrying value."><input required inputMode="decimal" className={input} value={impairment} onChange={event => changed(() => setImpairment(event.target.value))} /></Field>}{edit.kind === 'disposal' && <><div className="grid gap-4 sm:grid-cols-2"><Field label="Reviewed net disposal proceeds (PHP)"><input required inputMode="decimal" className={input} value={proceeds} onChange={event => changed(() => setProceeds(event.target.value))} /></Field><Field label="Reviewed final book depreciation (PHP)" hint="Enter 0 only when no final depreciation is required. It is not calculated automatically."><input required inputMode="decimal" className={input} value={finalDepreciation} onChange={event => changed(() => setFinalDepreciation(event.target.value))} /></Field></div><AccountSelect label="Dedicated disposal proceeds clearing account" accounts={usableAccounts(books, 'Asset').filter(account => !selected || ![selected.accounts.cost, selected.accounts.accumulatedDepreciation, selected.accounts.accumulatedImpairment].includes(account.code))} value={proceedsAccount} onChange={value => changed(() => setProceedsAccount(value))} /><p className="rounded-lg bg-amber-50 p-3 text-sm leading-6 text-amber-900">This action derecognizes the asset and records proceeds to a clearing account. Record actual cash collection and any applicable taxes separately to avoid duplicate receipts.</p></>}</>}
    {edit.kind !== 'register' && <Field label="Review basis and supporting reference"><textarea required className={`${input} min-h-24`} maxLength={2000} value={note} onChange={event => changed(() => setNote(event.target.value))} placeholder="Describe the evidence, policy, calculation and reason for this action." /></Field>}
    <label className="flex items-start gap-3 rounded-lg bg-muted/40 p-4 text-sm leading-6"><input type="checkbox" required className="mt-1.5" checked={confirmed} onChange={event => changed(() => setConfirmed(event.target.checked))} /><span>I checked the source records, dates, balances, policy choices and posting accounts. Any zero amounts are intentional.</span></label>
    {error && <p role="alert" className="rounded-lg bg-destructive/5 p-3 text-sm text-destructive">{error}</p>}
    <div className="flex flex-wrap gap-3"><Button type="submit" variant={ready ? 'outline' : 'default'} disabled={busy}>{ready ? 'Refresh preview' : 'Preview action'}</Button><Button type="button" variant="ghost" disabled={busy} onClick={close}>Cancel</Button></div>
    {ready && <><JournalPreview preview={ready.preview} books={books} />{stale && <p role="alert" className="rounded-lg bg-amber-50 p-3 text-sm text-amber-900">The books or asset register changed. Refresh the preview before saving.</p>}<Button type="button" disabled={busy || stale} onClick={() => void save()}><ClipboardCheck size={16} />{busy ? 'Saving…' : 'Save for independent review'}</Button></>}
    </form></Modal>
}
